# column count check for each row line
for l in open('fortress-gap-ledger.md'):
    if re.match(r'^\| \d+ \|', l):
        n=len(re.split(r'(?<!\\)\|', l.strip()))
        if n!=10: print("BADCOLS", n, l[:60])
